def _rotate(g, k):
    for _ in range(k):
        g = [list(row) for row in zip(*g[::-1])]
    return g


def _variants(g):
    for k in range(4):
        r = _rotate(g, k)
        yield r
        yield [row[::-1] for row in r]


def _corners(points):
    rs = [r for r, c in points]
    cs = [c for r, c in points]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    return {(r, c): (('T' if r == r0 else 'B') + ('L' if c == c0 else 'R'))
            for r, c in points}


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(cells)
    board = max(comps, key=len)
    r0, r1 = min(r for r, c in board), max(r for r, c in board)
    c0, c1 = min(c for r, c in board), max(c for r, c in board)
    panel = [row[c0:c1+1] for row in grid[r0:r1+1]]
    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] and not (r0 <= r <= r1 and c0 <= c <= c1)]
    colors = sorted({v for _, _, v in outside})
    target_points = {v: (r, c) for r, c, v in outside}
    target_sig = {v: sig for (r, c), sig in _corners({(rr, cc) for rr, cc, _ in outside}).items()
                  for rr, cc, vv in outside if (rr, cc) == (r, c)}
    # Use the three external colored markers to select the dihedral orientation
    # that places the same colors in the same relative corner positions.
    for candidate in _variants(panel):
        positions = {}
        for color in colors:
            found = [(r, c) for r, row in enumerate(candidate) for c, value in enumerate(row) if value == color]
            if len(found) != 1:
                break
            positions[color] = found[0]
        if len(positions) != len(colors):
            continue
        sigs = _corners(set(positions.values()))
        actual_sig = {color: sigs[pos] for color, pos in positions.items()}
        if actual_sig == target_sig:
            return candidate
    # A fallback for malformed/ambiguous markers: preserve the panel.
    return panel
